                    "low": { "type": "integer", "minimum": 0 }
                  }
                },
                "framework": {
                  "type": "object",
                  "additionalProperties": false,
                  "required": ["name", "version"],
                  "properties": {
                    "name": { "const": "swift-mutants" },
                    "version": { "type": "string" }
                  }
                },
                "files": {
                  "description": "Keyed by the path the repository uses, never by where the copy a run happened in was.",
                  "type": "object",
                  "additionalProperties": {
                    "type": "object",
                    "additionalProperties": false,
                    "required": ["language", "source", "mutants"],
