                "place": {
                  "description": "One-based, as the schema counts.",
                  "type": "object",
                  "additionalProperties": false,
                  "required": ["line", "column"],
                  "properties": {
                    "line": { "type": "integer", "minimum": 1 },
                    "column": { "type": "integer", "minimum": 1 }
                  }
                }
              }
            }
            """,
